// The old Chirpy theme installed an offline-cache service worker at this URL,
// which can keep showing the old site. This replacement deletes its caches,
// unregisters itself, and reloads open tabs so visitors get the current site.
self.addEventListener('install', function () { self.skipWaiting(); });

self.addEventListener('activate', function (event) {
  event.waitUntil((async function () {
    var keys = await caches.keys();
    await Promise.all(keys.map(function (k) { return caches.delete(k); }));
    await self.registration.unregister();
    var tabs = await self.clients.matchAll({ type: 'window' });
    tabs.forEach(function (tab) { tab.navigate(tab.url); });
  })());
});
